pub const shim_bin = @embedFile("shim.bin");

/// CH3's waves: encode each one the game uses, place them from `samples_addr`,
/// add their directory entries with `directory`, and write `wave.lut`'s bytes
/// at `wave_lut_addr`. The shim's own `segments` do not include those.
pub const wave = @import("wave.zig");

/// CH4's seven-bit samples: place `noise.encode()` right after the waves'
/// samples, and its `Noise.samples` directory entries (`noise.sampleAddr`, in
/// tier order) from source number `Noise.srcn_base`. Like the waves', they are the builder's
/// to place, because where they go depends on how many waves there are.
pub const noise = @import("noise.zig");

