pub const square_count: usize = 12;

/// A DSP directory entry: a sample's start and its loop point.
pub const SampleEntry = struct { start: u16, loop: u16 };

/// Entries the directory's page has room for, before the pitch table.
pub const directory_capacity: usize = (pitch_table_addr - dsp_dir_addr) / 4;

/// The DSP directory: the square bank's entries, then `extra` from source
/// number `square_count` on. Returns the bytes written.
pub fn directory(out: []u8, extra: []const SampleEntry) error{DirectoryFull}![]u8 {
    const n = square_count + extra.len;
    if (n > directory_capacity or out.len < n * 4) return error.DirectoryFull;
    @memcpy(out[0..square_directory.len], &square_directory);
    for (extra, square_count..) |e, i| {
        out[i * 4 + 0] = @truncate(e.start);
        out[i * 4 + 1] = @truncate(e.start >> 8);
        out[i * 4 + 2] = @truncate(e.loop);
        out[i * 4 + 3] = @truncate(e.loop >> 8);
    }
    return out[0 .. n * 4];
}

pub const Segment = struct { addr: u16, bytes: []const u8 };

/// The shim's own regions of ARAM, in ascending address order: what an image
/// builder places before adding the engine's. `config` is `config_hosted` or
/// `config_hosted_trace`; `dir` is `square_directory` or `directory`'s result.
pub fn segments(config: *const [config_size]u8, dir: []const u8) [6]Segment {
    return .{
        .{ .addr = 0x0200, .bytes = shim_bin },
        .{ .addr = 0x0d80, .bytes = &nck_table },
        .{ .addr = 0x0e28, .bytes = config },
        .{ .addr = 0x0e38, .bytes = &square_bank },
        .{ .addr = 0x0f00, .bytes = dir },
        .{ .addr = 0x1000, .bytes = &pitch_table },
    };
}
